// killable reports whether K has a process to signal (Rule 130).
//
// A protected process (DevDesk itself, the process that started it, PID 1, the
// Windows system processes) is greyed with the reason ports.Protection gives.
//
// A socket the system declines to attribute carries no PID — `List` blanks a
// PID of zero rather than printing it, because process 0 is a whole process
// group on Unix and a row reading "0" would look killable. That is the state
// this greys; whether the operating system will *accept* the signal is a
// different question, and one only the attempt can answer.
func (pm *PortsModel) killable() shortcut.Availability {
	entry, ok := pm.table.Selected()
	switch {
	case !ok:
		return shortcut.Unavailable(reasonNoSocketRow)
	case entry.PID == "":
		return shortcut.Unavailable(reasonNoPID)
	}
	if p := pm.ops.protection(entry.PID); p != ports.Unprotected {
		return shortcut.Unavailable(p.Reason())
	}
	// After the protection, as in ports.Kill: DevDesk's own row says what it
	// is, not that DevDesk cannot verify it. A deferred identity is verifiable:
	// it is read when the confirmation opens, never here.
	if !entry.Identity.Verifiable() {
		return shortcut.Unavailable(reasonUnverifiable)
	}
	// A stop in progress greys K on every row, after the reasons that belong to
	// the row. An exception to "an operation in progress is not a cause of
	// grey", imposed by the one-at-a-time criterion: it lasts at most the grace
	// and a modal, and the press says why.
	if s := pm.stop; s != nil {
		if s.target.PID == entry.PID {
			return shortcut.Unavailable(reasonStopPendingHere)
		}
		return shortcut.Unavailable(reasonAnotherStop)
	}

// both the state and the identity stamp, and the stamp is compared with listed,
// so a PID taken by another process reads as exited.
//
// A read that fails for another reason than "no such process" returns
// ProcessRunning with the error: an unreadable probe is never taken for a stop.
// Windows has no probe (errors.ErrUnsupported): it has no clean stop to watch.
func Probe(pid string, listed Identity) (Liveness, error) {
	n, ok := parsePID(pid)
	if !ok || n <= 0 {
		return ProcessRunning, fmt.Errorf("not a process id: %q", pid)
	}
	if listed.kind != identityKnown {
		return ProcessRunning, &UnverifiableError{PID: n}
	}
	if goos == "windows" {
		return ProcessRunning, fmt.Errorf("probing process %d: %w", n, errors.ErrUnsupported)
	}
	st, err := procOS.probe(n)
	return livenessOf(listed, st, err)
}

